# Configuration
SHA_BYTES = 32  # SHA-256 output = 32 bytes
SEED_BYTES = 32  # Match input length to SHA output
MAX_DEPTH = 1000  # Prevent infinite recursion

def sha256_bytes(data: bytes) -> bytes:
    return hashlib.sha256(data).digest()

def generate_seed(length=SEED_BYTES) -> bytearray:
    return bytearray(random.getrandbits(8) for _ in range(length))

def mirrored_match_score(input_bytes, hash_bytes):
    return sum(1 for i in range(len(input_bytes)) if input_bytes[i] == hash_bytes[-1 - i])

def recursive_collapse(seed: bytearray, depth=0, locked=None, history=None):
    if history is None:
        history = []
    if locked is None:
        locked = set()

    if depth > MAX_DEPTH:
        return seed, sha256_bytes(seed), history

    state = sha256_bytes(seed)
    history.append((seed[:], state[:], mirrored_match_score(seed, state)))

    # Base case: all mirrored bytes match
    if all(seed[i] == state[-1 - i] for i in range(len(seed))):
        return seed, state, history

    mid = len(seed) // 2
    # Generate list of symmetric pairs to check in recursive shell layers
    pairs = [(mid - i, len(seed) - (mid - i) - 1) for i in range(mid + 1) if (mid - i) >= 0 and (len(seed) - (mid - i) - 1) < len(seed)]

    for i, j in pairs:
        if i in locked or j in locked:
